import{_ as n,l as o,o as e,c as s,v as t,p as l,x as r,d as c,i as p,S as d}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"拍卖的结构估计","description":"","frontmatter":{"title":"拍卖的结构估计","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/auction-structural-estimation.md","filePath":"econ/auction-structural-estimation.md","lastUpdated":1789023840000}'),E={name:"econ/auction-structural-estimation.md"};function u(B,a,m,h,_,P){const i=o("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="拍卖的结构估计" tabindex="-1">拍卖的结构估计 <a class="header-anchor" href="#拍卖的结构估计" aria-label="Permalink to &quot;拍卖的结构估计&quot;">​</a></h1><div class="epigraph"><p>观测到的是出价，要的是估值分布；一阶条件把出价策略反演成估值，策略与信息结构写对了，反事实储备价才不是把历史成交均价再平均一次。</p><footer>—— Guerre, Perrigne and Vuong, Optimal Nonparametric Estimation of First-Price Auctions, Econometrica 2000；对照 Paarsch, Haile 的结构拍卖传统</footer></div><p><a href="/econ/production-function-estimation">上一课</a>从投入选择反演生产率。本课换博弈：第一价格密封拍卖里，出价 \\(b\\) 是估值 \\(v\\) 的策略。预测评估下一课离开结构、问预报精度。本课钉拍卖结构估计，不重写<a href="/econ/myerson-1981-paper">机制设计</a>附录全文。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>IPV 第一价格：对称贝叶斯纳什，\\(b=s(v)\\) 递增。观测到 \\(b\\) 的分布 \\(G\\)，Guerre–Perrigne–Vuong（GPV）用一阶条件</p> \\[v=b+\\frac{G(b)}{(n-1)g(b)}, \\]<p>非参数估 \\(G,g\\)，把每个 \\(b\\) 映回 \\(\\hat v\\)，得到估值分布 \\(F\\)。缺口是：储备价、进入、风险厌恶、关联价值会改这道反演。约化形式「谁赢了、成交价多少」回答不了「若提高储备价，期望收入如何」——那要 \\(F\\) 与策略一起变。</p><p><span class="marginnote">独立私人价值是最薄的许可证。关联价值、共同价值（石油租约）使赢家诅咒进入策略，GPV 公式不能直接套。Haile–Tamer 对英式拍卖给出部分识别，避免硬套 IPV。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>声明信息结构（IPV / 关联 / 共同）、规则（第一价格、英式、荷兰）、人数 \\(n\\) 是否外生。GPV：核估 \\(G,g\\)，注意边界偏误。参数途径：假定 \\(F\\) 族，用 MLE 或 GMM 拟合出价。进入内生：必须同时估进入成本，否则 \\(n\\) 对储备价的反应会错。风险厌恶：一阶条件多一个效用曲率，往往与 \\(F\\) 纠缠，识别要额外变体（不同 \\(n\\) 的场次）。</p>',10)),(e(),l(d,null,{default:r(()=>[p(i,{id:"mermaid-26",class:"mermaid",graph:"flowchart%20TD%0A%20%20BID%5B%22%E8%A7%82%E6%B5%8B%E5%87%BA%E4%BB%B7%20G%22%5D%20--%3E%20FOC%5B%22%E4%B8%80%E9%98%B6%E6%9D%A1%E4%BB%B6%E5%8F%8D%E6%BC%94%22%5D%0A%20%20FOC%20--%3E%20F%5B%22%E4%BC%B0%E5%80%BC%E5%88%86%E5%B8%83%20F%22%5D%0A%20%20F%20--%3E%20RF%5B%22%E5%8F%8D%E4%BA%8B%E5%AE%9E%E5%82%A8%E5%A4%87%E4%BB%B7%20%2F%20%E8%A7%84%E5%88%99%22%5D%0A%20%20INFO%5B%22%E4%BF%A1%E6%81%AF%E7%BB%93%E6%9E%84%E5%86%99%E9%94%99%22%5D%20--%3E%20WRONG%5B%22F%20%E4%B8%8D%E6%98%AF%E4%BC%B0%E5%80%BC%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与<a href="/econ/ipv-first-price">第一价格理论</a>：策略 \\(s(v)\\) 本课当估的对象的反函数，不重推均衡存在。Myerson 最优储备价是 \\(F\\) 估完之后的应用。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是最优出价把「再高一点的边际得物概率」与「多付的成本」对齐。密度 \\(g\\) 出现在分母：出价堆在某点，意味着估值密度与策略斜率的特定组合。估错 \\(g\\)（带宽过大抹掉峰值）会系统扭曲 \\(\\hat F\\) 的上尾——而最优储备价对上尾敏感。</p><p>与 BLP：都是从观测选择 / 出价反演不可观测（\\(\\xi\\) 或 \\(v\\)），再靠均衡做反事实。拍卖的均衡是贝叶斯博弈，产品市场是 Bertrand。工具在拍卖里往往是人数变化、场次协变量，排除要讲「\\(n\\) 不进估值」。</p><p><span class="marginnote">现场数据常有秘密储备、合谋、不对称。结构估计不是自动比 DiD 更真；合谋时 IPV 反演把策略误读成估值。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不给石油租约的新数字。不把英式拍卖的按钮模型与密封第一价格混用反演。下一课预报：对象是时间序列预测误差，不是估值。计量课程的结构支线在拍卖处给出「博弈 + 反演」的第二例，与离散选择、BLP、生产函数并列。</p><p>后课默认：拍卖反事实先写信息结构与一阶条件；GPV 只在 IPV 第一价格下直接用。\\(n\\) 内生、风险厌恶、共同价值都要改公式。不要用成交均价当「估值的无偏估计」。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>出价策略可反演估值，若信息结构与均衡写对。</li><li>GPV 用 \\(G,g\\) 非参数恢复 IPV 第一价格的 \\(F\\)。</li><li>反事实储备价在 \\(F\\) 上重解，不是历史均价。</li><li>合谋、共同价值、内生进入会毁掉套用。</li><li>出处：Guerre, Perrigne and Vuong, <em>Econometrica</em> 2000；Paarsch；Haile and Tamer。</li></ul>',10))])}const F=n(E,[["render",u]]);export{A as __pageData,F as default};
